   453	/**
   454	 * Conservative source classifier used by the contract smoke. Any production
   455	 * file that imports a provider adapter, is itself an adapter, or combines a
   456	 * child-process API with provider vocabulary must have an explicit inventory
   457	 * row. False positives are classified, never silently excluded, so adding a
   458	 * new direct provider spawn in a new file makes the contract fail closed.
   459	 */
   460	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   461	  if (!relativePath.endsWith('.ts')) return false;
   462	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   463	  if (relativePath === 'core/provider-process-registry.ts') return false;
   464	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   465	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   466	  if (/\brunHostRun\s*\(/.test(source)) return true;
   467	  // B-137a: strip documentation filename references before the provider-word
   468	  // scan. The words are matched case-insensitively, so a prose citation of
   469	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   470	  // read as a provider reference: any file that both used child_process for git
   471	  // and cited that doc became an "unclassified provider execution surface".
   472	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   473	  // convention -- a docs citation, not a provider workload. Several already
   474	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   475	  // runtime-environment-checks) match for the same non-reason. Stripping only
   476	  // "<provider>.md" filenames keeps every real provider reference intact,
   477	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   478	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
   479	  // B-137a: the provider word no longer requires a trailing \b. The old
   480	  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
   481	  // `codexRunner` all failed to match, because \b does not break between two
   482	  // word characters or before `_`. A file spawning a provider through such an
   483	  // identifier was therefore invisible to this tripwire (verified against the
   484	  // pre-change regex). A leading boundary is kept so unrelated substrings do not
   485	  // match, but the tail is now open so identifier and member forms are caught.
   486	  return /node:child_process/.test(source)
   487	    && /\b(?:codex|claude|agy|gemini|antigravity)/i.test(withoutDocReferences);
   488	}
