    53	    ['SCREAMING_SNAKE identifier', `${childProcess}const CLAUDE_CLI_PATH = '/x';`, true],
    54	    ['suffixed identifier', `${childProcess}const codexRunner = make();`, true],
    55	    ['gemini spawn', `${childProcess}spawn('gemini');`, true],
